const dbRows = $('Read Database').all().map(i => i.json);
const campaignRows = $('Read Campaigns').all().map(i => i.json);
const accountRows = $('Read Accounts').all().map(i => i.json);

// Index campaigns and accounts
const campaignsById = {};
for (const c of campaignRows) {
  const id = String(c.campaign_id ?? '').trim();
  if (id) campaignsById[id] = c;
}

const accountsByName = {};
for (const a of accountRows) {
  const name = String(a.account_name ?? '').trim();
  if (name) accountsByName[name] = a;
}

// Track sent today by account
const sentTodayByAccount = {};
for (const name in accountsByName) {
  sentTodayByAccount[name] = Number(accountsByName[name].connections_sent_today ?? 0);
}

function slugFromUrl(url) {
  if (!url) return null;
  const m = String(url).match(/\/in\/([^\/\?#]+)/i);
  return m ? m[1] : null;
}

const eligible = [];

for (const row of dbRows) {
  // Skip prospects that already have a connection attempt or reply logged
  const status = String(row.connection_request_status ?? '').trim();
  if (status !== '') continue;

  const reply = String(row.reply_received ?? '').trim();
  if (reply === 'Yes') continue;

  const cid = String(row.campaign_id ?? '').trim();
  const campaign = campaignsById[cid];
  if (!campaign) continue;

  const campaignStatus = String(campaign.campaign_status ?? '').trim();
  if (campaignStatus !== 'Active') continue;

  const sa = String(row.sending_account ?? '').trim();
  const account = accountsByName[sa];
  if (!account) continue;

  const accountStatus = String(account.status ?? '').trim();
  if (accountStatus !== 'active') continue;

  const acctName = String(account.account_name ?? '').trim();
  const limit = Number(account.connections_daily_limit ?? 0);
  const sent = Number(sentTodayByAccount[acctName] ?? 0);
  if (limit > 0 && sent >= limit) continue;

  sentTodayByAccount[acctName] = sent + 1;

  eligible.push({
    json: {
      campaignid: row.campaign_id,
      linkedinurl: row.linkedin_url,
      firstname: row.first_name,
      lastname: row.last_name,
      sendingaccount: row.sending_account,
      publicidentifier: slugFromUrl(row.linkedin_url),
      connectionnote: campaign.connection_note,
      unipileid: String(account.unipile_id ?? ''),
      unipileapi: account.unipile_api,
      unipiledsn: String(account.unipile_dsn ?? '')
    }
  });
}

return eligible;

const now = new Date();
const opts = {
  timeZone: 'Asia/Kolkata',
  hour12: false,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
};

const parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(now);
const get = (t) => parts.find(p => p.type === t)?.value || '';
const ts = `${get('day')}/${get('month')}/${get('year')} ${get('hour')}:${get('minute')}:${get('second')} IST`;

const prospect = $('Split In Batches').item.json;

return [
  {
    json: {
      linkedinurl: prospect.linkedinurl,
      providerid:$('Unipile: Get Provider ID').first().json.provider_id,
      connectionrequeststatus: 'Sent',
      connectionrequesttime: ts,
      failedreason: ''
    }
  }
];

const prospect = $('Split In Batches').item.json;
const accountRows = $('Read Accounts').all().map(i => i.json);

const acct = accountRows.find(a => a.account_name === prospect.sendingaccount);
if (!acct) return [];

return [
  {
    json: {
      accountname: acct.account_name,
      connectionssenttoday: Number(acct.connectionssenttoday || 0) + 1
    }
  }
];

const now = new Date();
const opts = {
  timeZone: 'Asia/Kolkata',
  hour12: false,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
};

const parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(now);
const get = (t) => parts.find(p => p.type === t).value;
const ts = `${get('day')}/${get('month')}/${get('year')} ${get('hour')}:${get('minute')}:${get('second')} IST`;

const prospect = $('Split In Batches').item.json;
const response = $input.first().json;
const reason = response.body
  ? (typeof response.body === 'string' ? response.body : JSON.stringify(response.body))
  : `HTTP ${response.statusCode || 'unknown'}`;

return [
  {
    json: {
      linkedinurl: prospect.linkedinurl,
      connectionrequeststatus: 'Failed',
      connectionrequesttime: ts,
      failedreason: `[${ts}] Invite failed: ${reason}`.slice(0, 500)
    }
  }
];

